UPDATE com_delivery_scope_project_version
SET scope_version = #{newScopeVersion}, payload_version = #{newPayloadVersion},
    last_change_type = #{changeType}, version = version + 1,
    updater = #{actor}, update_time = #{now}
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
  AND scope_version = #{expectedScopeVersion} AND version = #{expectedRowVersion}
  AND deleted = b'0'
